installer-gui-script.script:
// GnuPG where PGPM looks for it when started from Finder (GPG Suite, Homebrew)
function gnupgFound() {
    var paths = ['/usr/local/MacGPG2/bin/gpg', '/opt/homebrew/bin/gpg', '/usr/local/bin/gpg'];
    for (var i = 0; i < paths.length; i++) {
        if (system.files.fileExistsAtPath(paths[i])) {
            return true;
        }
    }
    return false;
}
